template<int BM,int BN,int NB,int SK,int NN,int KK,int BC,bool XCD,int MM>
struct bulk_allLDS_traits {
static constexpr int M=MM;
static_assert(MM>=16 && MM%16==0);
static constexpr int B_M=BM,B_N=BN,B_K=128,T_M=4,T_N=2,T_K=1;
static constexpr int BLOCK_SIZE=512,MR=BM/64,NR=BN/32,STAGES=NB,GLOBAL_SPLIT=SK;
static constexpr int N=NN,K=KK,B_CACHE=BC,TOTAL_SCALES=KK/128,PANELS=KK/(128*SK);
static constexpr bool XCD_ORDER=XCD,SB_SLOTS=PANELS%4!=0;
static constexpr int A_BYTES=BM*128,B_BYTES=BN*128,STAGE_BYTES=A_BYTES+B_BYTES;
static constexpr int A_COPIES=A_BYTES/(BLOCK_SIZE*16),B_COPIES=B_BYTES/(BLOCK_SIZE*16);
static constexpr int SA_POWER_ROWS=[]() constexpr {int r=16;while(r<BM)r*=2;return r;}();
static constexpr int SA_ORIGINAL_BYTES=((BM*PANELS+BLOCK_SIZE*16-1)/(BLOCK_SIZE*16))*(BLOCK_SIZE*16);
static constexpr int SA_PADDED_BYTES=((SA_POWER_ROWS*PANELS+BLOCK_SIZE*16-1)/(BLOCK_SIZE*16))*(BLOCK_SIZE*16);
static constexpr int SA_ROWS=SA_PADDED_BYTES==SA_ORIGINAL_BYTES?SA_POWER_ROWS:BM;
static constexpr int SA_BYTES=SA_ORIGINAL_BYTES;
static constexpr int SB_BYTES=BLOCK_SIZE*4,OFF_SA=NB*STAGE_BYTES,OFF_SB=OFF_SA+SA_BYTES;
static constexpr int SA_COPIES=SA_BYTES/(BLOCK_SIZE*16),ISSUES=A_COPIES+B_COPIES;
static constexpr int PIPELINE_BYTES=OFF_SB+SB_BYTES,OUTPUT_BYTES=BM*(BN+8)*2;
static constexpr int FLAG_OFF=PIPELINE_BYTES>OUTPUT_BYTES?PIPELINE_BYTES:OUTPUT_BYTES;
static constexpr int LDS_BYTES=FLAG_OFF+(SK>1?16:0);
static_assert((BM==64 || BM==128) && (BN==64 || BN==128));
static_assert(NB>=3 && NB<=6 && (SK==1 || SK==2 || SK==4));
static_assert(NN%128==0 && KK%(128*SK)==0 && PANELS>=NB-1);
static_assert(LDS_BYTES<=160*1024);
};
#if defined(__HIP_DEVICE_COMPILE__) && defined(__gfx950__)
__device__ __forceinline__ unsigned bulk_sfb_scalar_word(uint64_t base, unsigned offset) {
unsigned ready;
asm("s_load_dword %0, %1, %2"
: "=s"(ready) : "s"(base), "s"(offset));
return ready;
}
__device__ __forceinline__ unsigned bulk_sfb_scalar_complete(unsigned pending) {
asm volatile("" : "+s"(pending) : : "memory");
return pending;
}
__device__ __forceinline__ unsigned bulk_sfb_scalar_byte(unsigned word, unsigned shift) {
unsigned ready;
const unsigned field=0x80000u|shift;
asm("s_bfe_u32 %0, %1, %2"
: "=s"(ready) : "s"(word), "s"(field) : "scc");
return ready;
}
#endif
#if defined(__HIP_DEVICE_COMPILE__) && defined(__gfx950__)
__device__ __forceinline__ unsigned bulk_sfa_dword_byte(unsigned word, unsigned shift) {
unsigned byte;
asm("v_bfe_u32 %0, %1, %2, 8" : "=v"(byte) : "v"(word), "v"(shift));
return byte;
}
#endif

#if defined(__HIP_DEVICE_COMPILE__) && defined(__gfx950__)
template<class T> __device__ __forceinline__ 
void bulk_allLDS_kernel(opus_gemm_blockscale_mxscale_bpreshuffle_kargs_gfx950 args,float* partials,int* counters) {
using namespace opus;
constexpr int BM=T::B_M,BN=T::B_N,NB=T::STAGES,SK=T::GLOBAL_SPLIT,P=T::PANELS;
constexpr int MR=T::MR,NR=T::NR,N=T::N,K=T::K;
