if constexpr(SK>1) {
tile=pid/(8*SK)*8+pid%8;split=pid/8%SK;
if(tile>=total)return;
mtile=tile%gm;ntile=tile/gm;
} else {
if constexpr(T::XCD_ORDER)tile=pid%8*((total+7)/8)+pid/8;
else tile=pid;
if constexpr(T::XCD_ORDER)if(tile>=total)return;
mtile=tile/gn;ntile=tile%gn;
