auto gb=make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_b)+col*K,static_cast<unsigned>(BN*K));
auto gsa=make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfa),static_cast<unsigned>(M*T::TOTAL_SCALES));
