issue(0,begin);
static_for<T::SA_COPIES>([&](auto ii) {
constexpr int i=decltype(ii)::value;
const int index=(i*T::BLOCK_SIZE+tid)*16,sr=index%T::SA_ROWS,scol=index/T::SA_ROWS;
const int sc=scol<P?scol:P-1;
