__builtin_amdgcn_raw_ptr_buffer_load_async_lds(gsa.cached_rsrc,dst,16,source,0,0,0);
});
__builtin_amdgcn_sched_barrier(0);
static_for<NB-2>([&](auto si){issue(decltype(si)::value+1,begin+decltype(si)::value+1);});
auto step=[&](int t,unsigned sfb_uniform_t,int slot,auto pi,auto fi,auto li) {
constexpr bool last_panel=decltype(li)::value;
constexpr int pending=decltype(pi)::value;
constexpr bool future=decltype(fi)::value;
const unsigned sfb_byte_index=sfb_start_low+sfb_uniform_t*(T::B_K/128);
const unsigned sfb_pending=bulk_sfb_scalar_word(sfb_scalar_base,sfb_start_aligned+(sfb_byte_index&~3u));
const unsigned sfb_shift=(sfb_byte_index&3u)*8u;
__builtin_amdgcn_sched_barrier(0);
const unsigned ar_base=wm*(BM/4)+lane16;
