static_for<MR>([&](auto mi) {
constexpr int m=decltype(mi)::value;
as[m]=bulk_sfa_dword_byte(as[m],(lane16&3u)*8u);
static_for<NR>([&](auto ni) {
constexpr int n=decltype(ni)::value,ci=m*NR+n;
c[ci]=Base{}(af[m],bf[n],c[ci],static_cast<int>(as[m]),static_cast<int>(bs),0_I,0_I);
if constexpr(SK>1 && last_panel) {
using av_u32x4=unsigned __attribute__((ext_vector_type(4)));
const int64_t tile_base=int64_t(tile)*SK*BM*BN;
float* ptr=partials+tile_base+int64_t(split)*BM*BN+(ci*T::BLOCK_SIZE+tid)*4;
__builtin_amdgcn_av_store_b128(reinterpret_cast<__attribute__((address_space(1))) av_u32x4*>(reinterpret_cast<__UINTPTR_TYPE__>(ptr)),
__builtin_bit_cast(av_u32x4,c[ci]),__MEMORY_SCOPE_DEVICE);
