for(int group=0;group<GROUPS;++group) {
const unsigned sfb_uniform_group=__builtin_amdgcn_readfirstlane(static_cast<unsigned>(group));
static_for<NB>([&](auto phase) {
constexpr int ph=decltype(phase)::value;
step(group*NB+ph,sfb_uniform_group*NB+ph,ph,number<NB-2>{},number<true>{},number<false>{});
});
}
}
static_for<STEADY-REGULAR_END>([&](auto ti) {
constexpr int t=REGULAR_END+decltype(ti)::value;
step(t,t,t%NB,number<NB-2>{},number<true>{},number<false>{});
});
static_for<NB-1>([&](auto ti) {
constexpr int t=STEADY+decltype(ti)::value;
step(t,t,t%NB,number<P-t-1>{},number<false>{},number<t==P-1>{});
});
if constexpr(SK==1) {
constexpr int FRAGS=MR*NR;
const int side=(lane/16)%2;
static_for<FRAGS/2>([&](auto pi) {
constexpr int ci=decltype(pi)::value*2;
const auto first=__builtin_bit_cast(vector_t<unsigned,2>,cast<bf16_t>(c[ci]));
const auto second=__builtin_bit_cast(vector_t<unsigned,2>,cast<bf16_t>(c[ci+1]));
