static constexpr int SA_PADDED_BYTES=((SA_POWER_ROWS*SCALE_COLS+BLOCK_SIZE*16-1)/(BLOCK_SIZE*16))*(BLOCK_SIZE*16);
static constexpr int SA_ROWS=SA_PADDED_BYTES==SA_ORIGINAL_BYTES?SA_POWER_ROWS:BM;
