static_for<SK>([&](auto si) {
constexpr int s=decltype(si)::value;
auto source=make_gmem(partials+int64_t(s)*elements,static_cast<unsigned>(elements*4));
static_for<4>([&](auto pi) {
constexpr int p=decltype(pi)::value;inputs[s][p]=load<4>(source,index+p*4);
});
});
__builtin_amdgcn_sched_barrier(0);
s_waitcnt_vmcnt(0_I);
vector_t<float,16> sum{};
static_for<SK>([&](auto si) {
constexpr int s=decltype(si)::value;
static_for<4>([&](auto pi) {
constexpr int p=decltype(pi)::value;
static_for<4>([&](auto ei) {constexpr int e=decltype(ei)::value;sum[p*4+e]+=inputs[s][p][e];});
});
});
