const uint64_t flags_offset=(uint64_t(Traits::GLOBAL_SPLIT)*tiles*Traits::B_M*Traits::B_N*4+15)&~uint64_t(15);
const uint64_t required=flags_offset+((uint64_t(tiles)*4+15)&~uint64_t(15));
if(bytes!=required)return -12;
const void* inputs[]={a,b,out,sfa,sfb};
