}
__device__ __forceinline__ unsigned bulk_sfb_scalar_complete(unsigned pending) {
unsigned ready;
asm volatile("s_waitcnt lgkmcnt(0)\n\ts_mov_b32 %0, %1"
: "=s"(ready) : "s"(pending) : "memory");
