__device__ __forceinline__ unsigned bulk_sfb_scalar_word(uint64_t base, unsigned offset) {
unsigned ready;
asm volatile("s_load_dword %0, %1, %2\n\ts_waitcnt lgkmcnt(0)"
: "=s"(ready) : "s"(base), "s"(offset) : "memory");
